const BANNER_IMAGES=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const IMAGES=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const defaults={names:'Clarence & Vimbai',date:'2026-12-12',venue:'Venue to be announced',address:'',programme:'13:00 · Guest arrival & welcome drinks\n14:00 · Wedding ceremony\n15:00 · Family photographs\n16:00 · Reception & dinner\n19:00 · Speeches\n20:00 · Dancing & celebrations'};
const json=(x,status=200)=>Response.json(x,{status,headers:{'Cache-Control':'no-store'}});
export default {async fetch(req,env){try{const u=new URL(req.url),p=u.pathname;const admin=req.headers.get('Authorization')==='Bearer '+env.ADMIN_PASSWORD&&!!env.ADMIN_PASSWORD;const bucket=env.BUCKET;async function get(k){let o=await bucket.get(k);return o?o.json():null}async function put(k,v){await bucket.put(k,JSON.stringify(v))}async function list(prefix){let out=[],cursor;do{let r=await bucket.list({prefix,cursor});out.push(...r.objects);cursor=r.truncated?r.cursor:undefined}while(cursor);return out}
if(p.startsWith('/api/')){if(!bucket)return json({error:'Storage is not connected'},503);
if(p==='/api/settings'){if(req.method==='POST'){if(!admin)return json({error:'Please sign in'},401);let d=await req.json();await put('settings',d);return json({ok:true})}const s=await get('settings')||defaults;const g=u.searchParams.get('token');const allowed=admin||(g&&(await get('rsvp/'+g))?.status==='approved');return json(allowed?s:{names:s.names,date:s.date})}
if(p==='/api/rsvp'&&req.method==='POST'){let d=await req.json();if(!d.name||!/^\S+@\S+\.\S+$/.test(d.email)||!Number.isInteger(+d.guests)||+d.guests<1||+d.guests>8)return json({error:'Please check your name, email and guest count.'},400);let id=crypto.randomUUID();await put('rsvp/'+id,{...d,id,status:d.attending==='yes'?'pending':'declined',created:new Date().toISOString()});return json({id})}
if(p==='/api/admin'){if(!admin)return json({error:'Incorrect password'},401);if(req.method==='POST'){let d=await req.json(),r=await get('rsvp/'+d.id);if(!r)return json({error:'Response not found'},404);r.status=d.status;await put('rsvp/'+d.id,r);return json({ok:true})}return json(await Promise.all((await list('rsvp/')).map(o=>get(o.key))))}
const token=u.searchParams.get('token');const guest=token?await get('rsvp/'+token):null;const approved=guest?.status==='approved';
if(p==='/api/status')return json(guest?{name:guest.name,status:guest.status}:{status:'unknown'});
if(p==='/api/photos'){if(!approved&&!admin)return json({error:'Photo sharing opens after RSVP approval.'},403);if(req.method==='POST'){const f=await req.formData(),files=f.getAll('photos');if(files.length<4||files.length>12)return json({error:'Select 4–12 photos.'},400);for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)return json({error:'Use JPG, PNG or WebP photos under 8 MB.'},400)}for(const f of files)await bucket.put('photos/'+crypto.randomUUID(),f.stream(),{httpMetadata:{contentType:f.type}});return json({ok:true})}return json((await list('photos/')).map(o=>o.key))}
if(p.startsWith('/api/photo/')){if(!approved&&!admin)return json({error:'Approval required'},403);let o=await bucket.get('photos/'+p.split('/').pop());return o?new Response(o.body,{headers:{'Content-Type':o.httpMetadata.contentType}}):new Response('',{status:404})}return json({error:'Not found'},404)}
return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}})
}catch(e){return json({error:'Unable to complete the request. Please try again.'},500)}}};
const html=String.raw`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Clarence & Vimbai — A celebration of love</title><style>
:root{--green:#344b37;--cream:#f7f3e9;--gold:#b99955;--ink:#2f362c}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.6 Georgia,serif}button,input,select,textarea{font:14px/1.5 Arial,sans-serif}button,a{ -webkit-tap-highlight-color:transparent}button,.button{cursor:pointer;background:var(--green);color:white;border:1px solid var(--green);padding:14px 24px;border-radius:3px;text-decoration:none;display:inline-block}button:hover,.button:hover{background:#48634b}a{color:inherit}header{height:88px;display:flex;align-items:center;justify-content:space-between;padding:0 6%;border-bottom:1px solid #dad7cb;background:var(--cream);position:relative;z-index:5}.header-left{display:flex;align-items:center;gap:20px}.header-left summary{width:44px;height:44px;display:flex;align-items:center;justify-content:center}.header-left .dropdown{left:0;right:auto;top:48px}.brand{font-size:28px;text-decoration:none}.brand em{color:var(--gold);font-size:20px}nav{display:flex;align-items:center;gap:30px;font:12px Arial;letter-spacing:1px}nav a{text-decoration:none}details{position:relative}summary{cursor:pointer;list-style:none}.dropdown{position:absolute;right:0;top:30px;width:220px;background:var(--cream);padding:20px;box-shadow:0 10px 30px #0002}.dropdown a{display:block;padding:9px}.hero{min-height:670px;display:grid;grid-template-columns:48% 52%;position:relative}.intro{padding:85px 10% 75px 13%;background:radial-gradient(ellipse at top left,#e0e4d2,transparent 60%)}.eyebrow{font:10px/1.8 Arial;letter-spacing:3px;text-transform:uppercase;color:#66705a}.ornament{color:var(--gold);font-size:34px}.intro h1{font-size:clamp(55px,6vw,88px);line-height:1.03;font-weight:400;margin:18px 0}.intro h1 i{color:var(--gold);font-weight:400}.intro p{max-width:330px;color:#626653;font-size:17px}.date{font:12px Arial;letter-spacing:3px;margin:30px 0}.portrait{position:relative;background:#d8dbc9;overflow:hidden;isolation:isolate}.portrait img{width:100%;height:100%;position:absolute;inset:0}.portrait .banner-backdrop{object-fit:cover;filter:blur(24px) brightness(.75);transform:scale(1.12);z-index:-1}#banner{object-fit:contain;object-position:center;transition:opacity .5s}.portrait:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#172b2960,transparent 45%)}.photo-caption{position:absolute;bottom:35px;left:35px;color:white;z-index:1;letter-spacing:2px;font:11px Arial}.dots{position:absolute;right:35px;bottom:30px;z-index:2;display:flex;gap:10px}.dots button{padding:0;width:9px;height:9px;background:#fff6;border:1px solid white;border-radius:50%}.dots .active{background:white}.rsvp-link{margin-left:16px;font:11px Arial;letter-spacing:1px}.countdown{background:var(--green);color:white;padding:27px;display:flex;justify-content:center;align-items:center;gap:60px}.countdown span{font-size:28px;display:block;text-align:center}.countdown small{font:9px Arial;letter-spacing:2px;color:#dcdcc9}.count-label{font-style:italic;color:#d8c591}.section{padding:85px 7%;max-width:1300px;margin:auto}.section h2{font-size:46px;line-height:1.2;font-weight:400;margin:12px 0 24px}.center{text-align:center}.muted{color:#747763}.story{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}.collage{display:grid;grid-template-columns:1fr 1fr;gap:15px}.collage img{width:100%;height:290px;object-fit:cover;border-radius:130px 130px 3px 3px}.collage img:nth-child(2){margin-top:60px}.story p{max-width:460px}.swatches{display:flex;gap:12px;justify-content:center;margin:25px}.swatches i{width:35px;height:35px;border-radius:50%;border:1px solid #0001}.palette{background:#eeece1;text-align:center;padding:45px 20px}.palette h3{font-weight:400;font-size:28px;margin:0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-top:35px}.card{border:1px solid #d9d8c8;padding:32px;text-align:center}.card h3{font-size:26px;font-weight:400}.icon{font-size:32px;color:var(--gold)}footer{padding:40px;text-align:center;border-top:1px solid #ddd9c9;font-size:13px}footer a{color:#727761}.page{min-height:75vh;max-width:1000px;margin:auto;padding:65px 25px}.page h1{font-size:48px;font-weight:400}.form{max-width:600px;margin:30px auto;padding:32px;background:#eeede3}.form label{display:block;font:12px Arial;margin:20px 0 7px}.form input,.form select,.form textarea{width:100%;padding:13px;border:1px solid #cbcdbb;background:#fffdf7;color:#2f362c;border-radius:2px}.form textarea{min-height:100px}.form button{margin-top:22px}.notice{padding:20px;border:1px solid #c8cdbb;background:#edefe4;margin:20px 0}.hidden{display:none!important}.timeline{max-width:600px;margin:35px auto}.event{padding:22px;border-left:1px solid var(--gold);border-bottom:1px solid #dedccb;font-size:20px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font:13px Arial}td,th{padding:15px;text-align:left;border-bottom:1px solid #ddd}td button{padding:8px;margin:3px}.tag{padding:5px 9px;background:#e7e9db}.photo-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.photo-grid img{width:100%;height:190px;object-fit:cover}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:var(--green);color:white;padding:15px 25px;z-index:20;max-width:90vw}button:focus-visible,a:focus-visible{outline:3px solid var(--gold);outline-offset:4px}@media(max-width:700px){header{height:72px;padding:0 6%}nav{gap:18px}.nav-story{display:none}.hero{display:flex;flex-direction:column-reverse}.portrait{height:clamp(440px,125vw,680px)}.intro{padding:40px 8%}.intro h1{font-size:63px}.countdown{gap:24px}.count-label{display:none}.story{grid-template-columns:1fr;gap:40px}.section{padding:55px 7%}.section h2{font-size:38px}.collage img{height:240px}.cards{grid-template-columns:1fr}.photo-grid{grid-template-columns:repeat(2,1fr)}.form{padding:22px}.page h1{font-size:39px}}
</style><header><div class="header-left"><details><summary aria-label="Open menu"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg></summary><div class="dropdown"><a href="#venue">Venue & directions</a><a href="#programme">The programme</a><a href="#food">Food & dietary needs</a><a href="#gifts">Gifts</a><a href="#photos">Share your photos</a><a href="#status">My RSVP</a></div></details><a class="brand" href="#home">C <em>&</em> V</a></div><nav><a href="#rsvp">RSVP ↗</a></nav></header><main id="app"></main><footer><div class="brand">C <em>&</em> V</div><p>With love, always.</p></footer><div id="toast" class="toast hidden" role="status"></div><script>
const images=${JSON.stringify(IMAGES)}, bannerImages=${JSON.stringify(BANNER_IMAGES)}, D=${JSON.stringify(defaults)};let settings=D,adminKey='',timer,slide=0;const app=document.getElementById('app');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const token=()=>new URLSearchParams(location.search).get('guest')||localStorage.getItem('wedding-rsvp')||'';
async function api(path,opts={}){let r=await fetch('/api/'+path,{...opts,headers:{...opts.headers,...(adminKey?{Authorization:'Bearer '+adminKey}:{})}});let d=await r.json();if(!r.ok)throw Error(d.error||'Please try again');return d}function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),4500)}function page(title,body){app.innerHTML='<section class="page"><div class="eyebrow">THE WEDDING OF '+esc(settings.names)+'</div><h1>'+title+'</h1>'+body+'</section>'}
function home(){app.innerHTML='<section class="hero"><div class="intro"><div class="eyebrow">Together, for a brighter tomorrow</div><div class="ornament">❧</div><h1>You’re<br><i>Invited</i></h1><div class="date">'+esc(settings.names.toUpperCase())+'<br><br>'+new Date(settings.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}).toUpperCase()+'</div><p>We would be so happy for you to celebrate this special day with us.</p><a class="button" href="#rsvp">Kindly RSVP ↗</a></div><div class="portrait"><img id="banner-backdrop" class="banner-backdrop" src="'+bannerImages[0]+'" alt="" aria-hidden="true"><img id="banner" src="'+bannerImages[0]+'" alt="Clarence and Vimbai wedding portrait"><div class="photo-caption">OUR FOREVER BEGINS HERE</div><div class="dots">'+bannerImages.map((_,i)=>'<button aria-label="View photo '+(i+1)+'" class="'+(!i?'active':'')+'" onclick="showSlide('+i+')"></button>').join('')+'</div></div></section><div class="countdown"><div class="count-label">Counting down to forever</div>'+['days','hours','minutes','seconds'].map(x=>'<div><span id="'+x+'">—</span><small>'+x.toUpperCase()+'</small></div>').join('')+'</div><div class="palette"><div class="eyebrow">A LITTLE INSPIRATION</div><h3>The colours of our celebration</h3><div class="swatches"><i style="background:#455b3b"></i><i style="background:#e7be59"></i><i style="background:#e6dec9"></i><i style="background:#858872"></i></div><p class="muted">Olive green · Golden yellow · Warm cream · Sage</p></div>';tick();timer=setInterval(()=>{tick();showSlide((slide+1)%bannerImages.length)},5000)}
function showSlide(n){slide=n;let b=document.getElementById('banner');if(b){b.src=bannerImages[n];document.getElementById('banner-backdrop').src=bannerImages[n];b.alt=['Clarence and Vimbai wedding portrait','Clarence and Vimbai together','Clarence in the garden','Vimbai in the garden'][n];document.querySelectorAll('.dots button').forEach((x,i)=>x.classList.toggle('active',i===n))}}function tick(){let diff=Math.max(0,new Date(settings.date+'T13:00:00+02:00')-Date.now());let vals=[Math.floor(diff/86400000),Math.floor(diff/3600000)%24,Math.floor(diff/60000)%60,Math.floor(diff/1000)%60];['days','hours','minutes','seconds'].forEach((x,i)=>{let e=document.getElementById(x);if(e)e.textContent=vals[i]})}
async function approved(){let s=await api('status?token='+encodeURIComponent(token()));if(s.status==='approved')return true;page('A little more to look forward to','<div class="notice">Venue details, the programme and photo sharing open after your RSVP has been approved.</div><a class="button" href="#rsvp">Send your RSVP</a> <a href="#status">Check my RSVP</a>');return false}
async function render(){clearInterval(timer);document.querySelector('details').open=false;const route=location.hash.slice(1)||'home';window.scrollTo(0,0);try{if(route==='home'){home();return}if(route==='rsvp'||route==='food'){page(route==='food'?'Food & dietary preferences':'We’ve saved you a place','<p class="muted">Please let us know if you can join us. Your response will be reviewed by the bride and groom.</p><form id="rsvp" class="form"><label for="name">Full name *</label><input id="name" name="name" required maxlength="100"><label for="email">Email address *</label><input id="email" name="email" type="email" required maxlength="200"><label for="attending">Will you be attending? *</label><select id="attending" name="attending"><option value="yes">Joyfully accepts</option><option value="no">Regretfully declines</option></select><label for="guests">Number of guests, including you *</label><select id="guests" name="guests">'+[1,2,3,4,5,6,7,8].map(n=>'<option>'+n+'</option>').join('')+'</select><label for="meal">Food preference</label><select id="meal" name="meal"><option>No preference</option><option>Vegetarian</option><option>Vegan</option><option>Halal</option><option>Other — specify below</option></select><label for="diet">Allergies & dietary requirements for your party</label><textarea id="diet" name="diet" maxlength="2000" placeholder="Please include guest names and any allergies."></textarea><p class="muted">Your contact details and dietary needs will be shared only with the couple for wedding planning.</p><button>Submit RSVP ↗</button></form>');document.getElementById('rsvp').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{let d=await api('rsvp',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});localStorage.setItem('wedding-rsvp',d.id);location.hash='status'}catch(e){toast(e.message)}finally{b.disabled=false}};return}
if(route==='gifts'){page('A gift from the heart','<div class="center" style="max-width:600px;margin:35px auto"><div class="ornament">♡</div><p class="muted">Your presence is the greatest gift. If you would like to bless us with a contribution as we begin this new chapter, you can send your gift using EcoCash.</p><div class="notice"><div class="eyebrow">ECOCASH</div><p style="font-size:32px;letter-spacing:2px;margin:15px 0"><a href="tel:0783789153" style="text-decoration:none">0783789153</a></p><p class="muted" style="margin-bottom:0">Thank you for your love and generosity.</p></div></div>');return}
if(route==='status'){let s=await api('status?token='+encodeURIComponent(token()));page(s.status==='approved'?'You’re on the guest list!':s.status==='pending'?'Thank you for your RSVP':s.status==='declined'?'Thank you for letting us know':'Your RSVP','<div class="notice">'+({approved:'We can’t wait to celebrate with you. Your wedding details are now open.',pending:'Your response has been received. The bride and groom will review it shortly. Save this private link to check your approval status.',declined:'We’ll miss you and appreciate your warm wishes.',unknown:'Send an RSVP first, or use the personal link saved when you responded.'}[s.status])+'</div>'+(token()?'<p><a href="?guest='+encodeURIComponent(token())+'#status">Your personal RSVP link — save this</a></p>':'')+(s.status==='approved'?'<a class="button" href="#venue">Enter the guest lounge ↗</a>':'<button onclick="render()">Refresh status</button>'));return}
if(route==='venue'||route==='programme'||route==='photos'){if(!await approved())return;if(route==='venue'){page('A beautiful place to say “I do”','<div class="notice"><h2>'+esc(settings.venue)+'</h2><p>'+esc(settings.address||'The couple will add the full address soon.')+'</p>'+(settings.address?'<a class="button" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(settings.address)+'">Open Google Maps directions ↗</a>':'')+'</div>');return}if(route==='programme'){page('The programme','<p class="muted">A little guide to our celebration. Draft timings, subject to confirmation.</p><div class="timeline">'+settings.programme.split('\n').map(x=>'<div class="event">'+esc(x)+'</div>').join('')+'</div>');return}page('Through your eyes','<p class="muted">The candid moments. The happy tears. The dance floor. Share 4–12 photos at a time to help us remember it all.</p><form id="upload" class="form"><label for="files">Select at least 4 photos</label><input id="files" name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple required><p class="muted">JPG, PNG or WebP · up to 8 MB each. Photos are visible to approved guests.</p><button>Upload memories ↗</button></form><div id="gallery" class="photo-grid"></div>');let photos=await api('photos?token='+token());document.getElementById('gallery').innerHTML=photos.map(p=>'<img loading="lazy" alt="A shared wedding memory" src="/api/photo/'+p.split('/')[1]+'?token='+token()+'">').join('');document.getElementById('upload').onsubmit=async e=>{e.preventDefault();let btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='Uploading…';try{await api('photos?token='+token(),{method:'POST',body:new FormData(e.target)});toast('Your memories have been saved. Thank you!');render()}catch(e){toast(e.message);btn.disabled=false;btn.textContent='Upload memories ↗'}};return}
if(route==='admin'){if(!adminKey){page('A space for the two of you','<p class="muted">Manage your guest list and the details of your day.</p><form id="login" class="form"><label for="password">Couple’s password</label><input id="password" type="password" required autocomplete="current-password"><button>Open dashboard ↗</button></form>');document.getElementById('login').onsubmit=async e=>{e.preventDefault();adminKey=document.getElementById('password').value;try{await api('admin');render()}catch(e){adminKey='';toast(e.message)}};return}await dashboard();return}home()}catch(e){page('One moment, please','<div class="notice">'+esc(e.message)+'</div><button onclick="render()">Try again</button>')}}
async function dashboard(){settings=await api('settings');let rows=await api('admin');page('Your wedding, at a glance','<button onclick="adminKey=\'\';render()" style="float:right">Sign out</button><p class="muted">'+rows.filter(r=>r.status==='pending').length+' awaiting approval · '+rows.filter(r=>r.status==='approved').reduce((a,r)=>a+Number(r.guests),0)+' approved guests</p><div class="table-wrap"><table><thead><tr><th>Guest</th><th>Party</th><th>Dietary needs</th><th>Status</th><th>Manage RSVP</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.name)+'<br>'+esc(r.email)+'</td><td>'+esc(r.guests)+'</td><td>'+esc(r.meal)+'<br>'+esc(r.diet)+'</td><td><span class="tag">'+esc(r.status)+'</span></td><td><button onclick="changeStatus(\''+r.id+'\',\'approved\')">Approve</button><button onclick="changeStatus(\''+r.id+'\',\'declined\')">Decline</button><a href="?guest='+r.id+'#status" target="_blank">Guest link ↗</a></td></tr>').join('')+(rows.length?'':'<tr><td colspan="5">No responses yet. They will appear here as guests RSVP.</td></tr>')+'</tbody></table></div><p class="muted">After approval, copy the guest’s personal link and send it to them. Emails are not sent automatically.</p><h2>Wedding details</h2><form id="settings" class="form">'+[['names','Couple’s names'],['date','Wedding date'],['venue','Venue name'],['address','Full venue address']].map(([k,l])=>'<label for="s-'+k+'">'+l+'</label><input id="s-'+k+'" name="'+k+'" '+(k==='date'?'type="date"':'')+' required value="'+esc(settings[k])+'">').join('')+'<label for="s-programme">Programme (one event per line)</label><textarea id="s-programme" name="programme" style="min-height:200px">'+esc(settings.programme)+'</textarea><button>Save wedding details</button></form>');document.getElementById('settings').onsubmit=async e=>{e.preventDefault();try{let d=Object.fromEntries(new FormData(e.target));await api('settings',{method:'POST',body:JSON.stringify(d)});settings=d;toast('Wedding details saved')}catch(e){toast(e.message)}}}
async function changeStatus(id,status){try{await api('admin',{method:'POST',body:JSON.stringify({id,status})});await dashboard();toast('RSVP '+status)}catch(e){toast(e.message)}}window.addEventListener('hashchange',render);api('settings?token='+encodeURIComponent(token())).then(d=>{settings=d;render()}).catch(()=>render());
</script></html>`;
